-- Script 125 · parte 4 de 6: depósitos de la organización 3 y su detalle contable (717 depósitos y 0 líneas).
--   Ejecutar las 6 partes en orden en el SQL Editor de Supabase. Es el mismo script 125 partido: el resultado es
--   igual a ejecutarlo completo, y cada parte se puede ejecutar de nuevo (solo actualiza).
alter table public.movimientos_bancarios add column if not exists deposito_anterior integer;
alter table public.movimientos_bancarios add column if not exists banco_anterior integer;
alter table public.movimientos_bancarios add column if not exists estatus_anterior text;
alter table public.movimientos_bancarios add column if not exists origen_anterior text;
alter table public.movimientos_bancarios add column if not exists conciliado_anterior text;
